import{_ as t,o as s,c as n,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Panel interne edPage","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"admission/staff-edpage/index.md","filePath":"src/admission/staff-edpage/index.md"}'),r={name:"admission/staff-edpage/index.md"};function i(o,e,l,u,d,c){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="panel-interne-edpage" tabindex="-1">Panel interne edPage <a class="header-anchor" href="#panel-interne-edpage" aria-label="Permalink to &quot;Panel interne edPage&quot;">​</a></h1><p>Le panel interne Era Admission est l&#39;outil réservé à l&#39;équipe edPage pour gérer le cycle de vie des établissements inscrits en ligne : accorder une licence, clore une démonstration avant terme, ou purger un établissement expiré. C&#39;est aussi là que l&#39;équipe modifie la <strong>vitrine</strong> d&#39;Era Admission et traite les <strong>demandes de contact</strong> qu&#39;elle reçoit. Il n&#39;a aucun rapport avec un compte utilisateur d&#39;un établissement client — c&#39;est un accès entièrement séparé.</p><p>Le menu en haut du panel mène à ses écrans : <strong>Établissements</strong>, <strong>Vitrine</strong>, <strong>Demandes de contact</strong>, <strong>Devis</strong> et <strong>Paiement en ligne</strong> (les demandes d&#39;activation du paiement en ligne). À droite, <strong>Voir la vitrine</strong> ouvre la page publique dans un nouvel onglet et <strong>Mot de passe</strong> mène au changement de votre propre mot de passe.</p><h2 id="se-connecter-au-panel" tabindex="-1">Se connecter au panel <a class="header-anchor" href="#se-connecter-au-panel" aria-label="Permalink to &quot;Se connecter au panel&quot;">​</a></h2><ol><li>Rendez-vous sur la page de connexion staff, accessible sur le domaine central d&#39;ERA (celui du site d&#39;inscription, pas le sous-domaine d&#39;un établissement).</li><li>Saisissez votre adresse e-mail et votre mot de passe <strong>de compte staff</strong> — ce compte est indépendant de tout compte d&#39;établissement, il n&#39;existe que pour l&#39;équipe edPage.</li><li>Validez. Vous arrivez sur la liste des établissements.</li></ol><p>Le formulaire de connexion staff est volontairement limité (pas d&#39;inscription libre, pas de double authentification, pas de « mot de passe oublié ») : les comptes staff sont créés à la main, pas via un flux public.</p><h2 id="changer-votre-mot-de-passe" tabindex="-1">Changer votre mot de passe <a class="header-anchor" href="#changer-votre-mot-de-passe" aria-label="Permalink to &quot;Changer votre mot de passe&quot;">​</a></h2><p>Votre compte vous est remis avec un mot de passe provisoire. Changez-le dès la première connexion :</p><ol><li>Cliquez sur <strong>Mot de passe</strong>, en haut à droite du panel.</li><li>Saisissez votre mot de passe actuel, puis le nouveau, deux fois.</li><li>Validez : un message confirme le changement.</li></ol><p>Comme ce panel n&#39;envoie aucun courriel de réinitialisation, un mot de passe oublié ne se récupère pas depuis l&#39;écran de connexion : demandez à l&#39;administrateur du serveur de vous en attribuer un nouveau, puis changez-le à nouveau ici après vous être connecté.</p><h2 id="consulter-la-liste-des-etablissements" tabindex="-1">Consulter la liste des établissements <a class="header-anchor" href="#consulter-la-liste-des-etablissements" aria-label="Permalink to &quot;Consulter la liste des établissements&quot;">​</a></h2><p>Une fois connecté, la page « Établissements » liste tous les établissements inscrits, avec pour chacun :</p><ul><li>son nom et son sous-domaine ;</li><li>son <strong>statut</strong> : gratuit, démo, licencié ou expiré ;</li><li>ses <strong>pôles</strong> actifs (aucun en gratuit ; tous en démo ; ceux effectivement licenciés en licencié ; aucun en expiré) ;</li><li>sa <strong>formule d&#39;hébergement</strong> (autonome ou clé en main) ;</li><li>la date de fin de démo, la date jusqu&#39;à laquelle la maintenance est payée, et depuis quand l&#39;établissement est expiré, selon ce qui s&#39;applique.</li></ul><p>Chaque ligne propose ensuite les actions disponibles pour cet établissement, décrites ci-dessous — certaines n&#39;apparaissent que pour certains statuts.</p><h2 id="accorder-une-licence" tabindex="-1">Accorder une licence <a class="header-anchor" href="#accorder-une-licence" aria-label="Permalink to &quot;Accorder une licence&quot;">​</a></h2><p>Disponible pour tout établissement, quel que soit son statut actuel.</p><ol><li>Sur la ligne de l&#39;établissement concerné, cliquez sur <strong>Licencier</strong>.</li><li>Dans la boîte de dialogue, cochez les pôles à accorder (ou l&#39;option « Offre complète » pour tous les pôles d&#39;un coup). Le tarif de chaque pôle est rappelé à côté de son nom.</li><li>Renseignez, si besoin, la date jusqu&#39;à laquelle la maintenance est payée. Laissée vide, elle est fixée automatiquement à un an à partir d&#39;aujourd&#39;hui.</li><li>Confirmez avec <strong>Octroyer la licence</strong>.</li></ol><p>L&#39;établissement passe immédiatement au statut « Licencié », avec les pôles cochés actifs, tout en restant hébergé sur l&#39;infrastructure edPage (formule « Clé en main »). Si l&#39;établissement doit finalement héberger lui-même son installation (formule « Autonome »), la bascule se fait par un outil en ligne de commande dédié, hors de ce panel — n&#39;utilisez pas cette action pour ce cas-là.</p><p>Cette action peut aussi être utilisée pour <strong>modifier</strong> la licence d&#39;un établissement déjà licencié (ajouter un pôle, prolonger la maintenance) : il suffit de la réappliquer avec les nouvelles valeurs.</p><h2 id="cloturer-une-demonstration-manuellement" tabindex="-1">Clôturer une démonstration manuellement <a class="header-anchor" href="#cloturer-une-demonstration-manuellement" aria-label="Permalink to &quot;Clôturer une démonstration manuellement&quot;">​</a></h2><p>Disponible uniquement pour un établissement au statut « Démo ». L&#39;action n&#39;apparaît pas sur les autres statuts.</p><ol><li>Sur la ligne de l&#39;établissement, cliquez sur <strong>Terminer la démo</strong>.</li><li>Confirmez dans la boîte de dialogue — l&#39;action est immédiate.</li></ol><p>L&#39;établissement passe au statut « Expiré » et repasse en lecture seule, exactement comme si sa démo s&#39;était terminée naturellement à l&#39;échéance prévue. Utilisez cette action pour mettre fin à une démo avant son terme normal (par exemple à la demande de l&#39;établissement, ou en cas d&#39;usage abusif) — ce n&#39;est pas nécessaire dans le cours normal des choses, la démo se termine d&#39;elle-même.</p><h2 id="purger-un-etablissement-expire" tabindex="-1">Purger un établissement expiré <a class="header-anchor" href="#purger-un-etablissement-expire" aria-label="Permalink to &quot;Purger un établissement expiré&quot;">​</a></h2><p>Disponible uniquement pour un établissement au statut « Expiré ». Cette action est <strong>définitive et irréversible</strong>.</p><ol><li>Sur la ligne de l&#39;établissement, cliquez sur <strong>Purger</strong>.</li><li>Relisez attentivement le message d&#39;avertissement dans la boîte de dialogue : il rappelle que l&#39;établissement, sa base de données et son stockage seront supprimés immédiatement, sans délai de grâce ni possibilité d&#39;annulation.</li><li>Confirmez avec <strong>Supprimer définitivement</strong>.</li></ol><p>Dans le cours normal des choses, un établissement expiré depuis trop longtemps est purgé automatiquement à l&#39;issue de son délai de grâce. Utilisez cette action manuelle uniquement pour purger un établissement avant l&#39;échéance automatique — par exemple à la demande explicite de l&#39;établissement de supprimer ses données sans attendre.</p><h2 id="modifier-la-vitrine" tabindex="-1">Modifier la vitrine <a class="header-anchor" href="#modifier-la-vitrine" aria-label="Permalink to &quot;Modifier la vitrine&quot;">​</a></h2><p>La vitrine est la page publique affichée à l&#39;adresse principale d&#39;Era Admission (le domaine central, pas le sous-domaine d&#39;un établissement). Elle présente l&#39;offre aux établissements et mène vers l&#39;inscription gratuite ou vers une demande de proposition, et son configurateur de tarifs permet à un établissement de composer sa licence et de demander un devis.</p><p>L&#39;écran <strong>Vitrine</strong> commence par l&#39;<strong>Apparence</strong> de la page, puis le bloc <strong>Sections de la page</strong> (l&#39;ordre des parties et les sections ajoutées). Il reprend ensuite chaque partie dans son ordre d&#39;affichage, et se termine par les <strong>Libellés</strong> et le <strong>Partage et référencement</strong>. Les parties d&#39;origine sont :</p><table tabindex="0"><thead><tr><th>Partie</th><th>Contenu modifiable</th><th>Affichage</th></tr></thead><tbody><tr><td><strong>En-tête</strong></td><td>Surtitre, titre et texte d&#39;accroche</td><td>Toujours</td></tr><tr><td><strong>En bref</strong></td><td>Une carte par point (quatre conseillés)</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Enseignements</strong></td><td>Surtitre, titre, texte, une carte par pôle</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Offre gratuite</strong></td><td>Surtitre, titre et texte</td><td>Si <strong>Afficher</strong> est coché</td></tr><tr><td><strong>Référentiels</strong></td><td>Surtitre, titre, texte, une carte par ligne du tableau</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Modules</strong></td><td>Surtitre, titre, texte, une carte par module</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Enseignement supérieur</strong></td><td>Surtitre, titre, texte, une carte par point</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Chez vous</strong></td><td>Surtitre, titre, texte, une carte par besoin</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Tarifs &amp; Devis</strong></td><td>Surtitre, titre, texte, cartes tarifées et conditions</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Mise en service</strong></td><td>Surtitre, titre, texte, une carte par étape</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une carte</td></tr><tr><td><strong>Foire aux questions</strong></td><td>Surtitre, titre, questions et réponses</td><td>Si <strong>Afficher</strong> est coché et qu&#39;il y a une question</td></tr><tr><td><strong>Contact</strong></td><td>Surtitre, titre et texte au-dessus du formulaire</td><td>Toujours</td></tr></tbody></table><p>Les dessins de la page (le tableau de bord et le portail des familles de l&#39;en-tête, la frise des niveaux, le formulaire d&#39;inscription, le bulletin, le suivi des paiements, les messages aux familles, le parcours de l&#39;étudiant, le schéma « hors connexion ») ne se modifient pas : leurs textes suivent la langue de la page, avec des noms fictifs.</p><p>Le <strong>surtitre</strong> est la petite ligne en capitales au-dessus du titre d&#39;une partie (« LES RÉFÉRENTIELS », « CONTACT »…). Les champs des formulaires de contact et de devis ne se modifient pas.</p><h3 id="choisir-l-apparence" tabindex="-1">Choisir l&#39;apparence <a class="header-anchor" href="#choisir-l-apparence" aria-label="Permalink to &quot;Choisir l&#39;apparence&quot;">​</a></h3><p>La partie <strong>Apparence</strong> règle le look de toute la page. Les couleurs et le logo restent ceux d&#39;ERA : la vitrine présente le produit.</p><ul><li><strong>Mise en page du haut de la page</strong> : <strong>Illustrée</strong> (le titre à gauche, un dessin du produit à droite, sans photo ; c&#39;est la mise en page par défaut), <strong>Centrée</strong> (le titre au centre), <strong>Plein écran</strong> (une photo sur toute la largeur, le texte par-dessus), <strong>Côte à côte</strong> (le texte à gauche, la photo à droite) ou <strong>Éditorial</strong> (un grand titre, puis la photo en bandeau). Les pastilles des pôles sous les boutons n&#39;apparaissent qu&#39;avec la mise en page <strong>Centrée</strong>.</li><li><strong>Image du haut de la page</strong> : la photo de l&#39;en-tête (PNG, JPG ou WebP, 4 Mo au plus), avec le <strong>voile</strong> qui l&#39;assombrit pour garder le texte lisible et le <strong>cadrage de l&#39;image</strong> (centre, haut, bas).</li><li><strong>Fond de la page</strong> : halo coloré, uni ou teinté.</li><li><strong>Afficher l&#39;icône du logo</strong> au-dessus du titre (le logo complet reste dans le bandeau du haut).</li><li><strong>Ambiance</strong> : les <strong>polices</strong> (<strong>Affirmé</strong> par défaut : des titres très gras), les <strong>angles</strong> des cadres, la forme des <strong>boutons</strong> et le <strong>fond des sections</strong>. Avec <strong>Couleur pleine</strong>, la mise en service passe sur la couleur principale ; les parties plus denses (enseignements, référentiels, enseignement supérieur, tarifs) restent sur une teinte pour rester lisibles.</li></ul><p>Sans changement, la page prend la mise en page <strong>Illustrée</strong> et la police <strong>Affirmé</strong>. Une apparence déjà enregistrée est conservée : pour passer au nouveau look, choisissez ces deux options puis enregistrez.</p><h3 id="ordonner-les-sections-et-en-ajouter" tabindex="-1">Ordonner les sections et en ajouter <a class="header-anchor" href="#ordonner-les-sections-et-en-ajouter" aria-label="Permalink to &quot;Ordonner les sections et en ajouter&quot;">​</a></h3><p>Le bloc <strong>Sections de la page</strong> liste toutes les parties sous l&#39;en-tête, dans leur ordre d&#39;affichage : celles d&#39;origine comme celles que vous ajoutez. Les flèches les montent ou les descendent. L&#39;en-tête reste toujours en haut de la page.</p><p><strong>Ajouter une section</strong> propose les mêmes types que la page d&#39;accueil d&#39;un établissement. La section s&#39;ajoute en bas de la liste, vide, avec son propre bloc dans l&#39;éditeur, et n&#39;apparaît sur la vitrine qu&#39;une fois remplie :</p><table tabindex="0"><thead><tr><th>Section</th><th>Contenu</th><th>Maximum</th></tr></thead><tbody><tr><td><strong>Chiffres clés</strong></td><td>Une valeur (« 120 », « 98 % ») et ce qu&#39;elle mesure</td><td>8 chiffres</td></tr><tr><td><strong>Galerie photos</strong></td><td>Des photos (captures d&#39;écran, formations…), légende facultative</td><td>24 photos</td></tr><tr><td><strong>Témoignages</strong></td><td>Le témoignage, son auteur, sa fonction, une photo facultative</td><td>12</td></tr><tr><td><strong>Actualités</strong></td><td>Titre, date, texte et image ; les plus récentes en premier</td><td>12</td></tr><tr><td><strong>Partenaires</strong></td><td>Le logo, le nom, et le site web vers lequel mène le logo</td><td>24</td></tr><tr><td><strong>Contact et accès</strong></td><td>Adresse, téléphone, e-mail, horaires, plan construit à partir de l&#39;adresse</td><td>—</td></tr><tr><td><strong>Vidéo</strong></td><td>L&#39;adresse d&#39;une vidéo YouTube ou Vimeo, et une légende</td><td>—</td></tr></tbody></table><p>La vitrine peut contenir jusqu&#39;à 12 sections ajoutées, plusieurs du même type si besoin. Chaque section ajoutée a un <strong>Surtitre</strong>, un <strong>Titre de la section</strong> et la case <strong>Afficher cette section sur la page</strong> ; <strong>Supprimer la section</strong> l&#39;efface avec tout son contenu, images comprises. Les six premières parties de la liste apparaissent dans le menu du bandeau du haut.</p><h3 id="modifier-les-libelles" tabindex="-1">Modifier les libellés <a class="header-anchor" href="#modifier-les-libelles" aria-label="Permalink to &quot;Modifier les libellés&quot;">​</a></h3><p>La partie <strong>Libellés</strong> change les textes qui n&#39;appartiennent à aucune partie : les boutons <strong>Créez votre compte gratuit</strong>, <strong>Créer mon compte</strong> (bandeau du haut) et <strong>Composer mon offre</strong>, la pastille <strong>Gratuit</strong> de l&#39;offre gratuite, et le nom affiché dans le pied de page après « © année » (edPage par défaut).</p><p>Elle contient aussi les coordonnées de la section Contact et du pied de page, remplies au départ avec celles d&#39;edPage :</p><ul><li><strong>E-mails</strong> et <strong>Téléphones</strong> : plusieurs valeurs séparées par des virgules. Ils apparaissent dans la carte de coordonnées de la section Contact et dans le pied de page.</li><li><strong>Adresse</strong> : affichée dans la section Contact.</li><li><strong>Mentions légales</strong> : la ligne affichée après « © année » en bas du pied de page.</li></ul><p>Un champ laissé vide fait disparaître sa ligne.</p><h3 id="partage-et-referencement" tabindex="-1">Partage et référencement <a class="header-anchor" href="#partage-et-referencement" aria-label="Permalink to &quot;Partage et référencement&quot;">​</a></h3><p>La partie <strong>Partage et référencement</strong> règle ce que Google et les aperçus de lien (WhatsApp, Facebook, LinkedIn…) montrent de la vitrine :</p><ul><li>le <strong>titre de la page</strong>, affiché dans l&#39;onglet du navigateur et dans les résultats de recherche, suivi de « - ERA » : une soixantaine de caractères au plus ;</li><li>la <strong>description</strong>, le résumé affiché sous le titre : environ 160 caractères ;</li><li>l&#39;<strong>image d&#39;aperçu</strong>, affichée quand le lien est partagé (1200 × 630 pixels conseillés). Sans image, la photo de l&#39;en-tête est utilisée.</li></ul><p>Les applications de messagerie gardent souvent un aperçu en mémoire plusieurs jours : un lien déjà partagé peut montrer l&#39;ancienne version un moment.</p><h3 id="textes-par-defaut" tabindex="-1">Textes par défaut <a class="header-anchor" href="#textes-par-defaut" aria-label="Permalink to &quot;Textes par défaut&quot;">​</a></h3><p>Chaque texte se saisit en français et en anglais. Un champ laissé vide affiche le texte par défaut de sa langue, visible en grisé dans le champ. Vous n&#39;avez donc à remplir que ce que vous voulez changer. Si vous n&#39;écrivez que dans une langue, ce texte est repris dans l&#39;autre.</p><p>À la première mise en service, toutes les parties à cartes et la foire aux questions sont déjà remplies à partir de la proposition commerciale. Modifiez-les ou supprimez-les librement.</p><h3 id="gerer-les-cartes-et-les-questions" tabindex="-1">Gérer les cartes et les questions <a class="header-anchor" href="#gerer-les-cartes-et-les-questions" aria-label="Permalink to &quot;Gérer les cartes et les questions&quot;">​</a></h3><ul><li><strong>Ajouter une carte</strong> ou <strong>Ajouter une question</strong> ouvre un formulaire ; le titre (ou la question et la réponse) est obligatoire dans au moins une langue.</li><li>Les flèches <strong>Monter</strong> et <strong>Descendre</strong> changent l&#39;ordre d&#39;affichage. Pour <strong>Mise en service</strong>, cet ordre est aussi la numérotation des étapes sur la page.</li><li><strong>Modifier</strong> rouvre l&#39;élément ; <strong>Supprimer</strong> le retire définitivement.</li></ul><p>Chaque bloc indique son état : <strong>Affichée</strong>, <strong>Masquée</strong> (décochée) ou <strong>Vide, non affichée</strong> (aucune carte ou question). Les enregistrements sont immédiats.</p><h3 id="ecrire-les-textes-de-la-vitrine" tabindex="-1">Écrire les textes de la vitrine <a class="header-anchor" href="#ecrire-les-textes-de-la-vitrine" aria-label="Permalink to &quot;Écrire les textes de la vitrine&quot;">​</a></h3><p>Quelques conventions de saisie donnent leur forme aux parties :</p><ul><li><strong>Titre de l&#39;en-tête</strong> : les mots entre crochets s&#39;affichent en couleur avec la mise en page <strong>Illustrée</strong>, par exemple « De la petite enfance [à l&#39;université]. » Les crochets n&#39;apparaissent jamais sur la page, quelle que soit la mise en page.</li><li><strong>Offre gratuite</strong> : le premier paragraphe du texte présente l&#39;offre ; chaque paragraphe suivant devient une étape cochée, sa première phrase en gras (« Marche 1, ERA Admissions. »). Séparez les paragraphes par une ligne vide.</li><li><strong>Cartes Enseignements et Modules</strong> : la première ligne de la description est l&#39;accroche (le titre du module, ou la présentation du pôle) ; chaque ligne qui commence par « - » devient un point de la liste.</li><li><strong>Module illustré</strong> (cartes Modules) : le module que la carte présente. <strong>Vie académique</strong>, <strong>Finances</strong> et <strong>Relation famille</strong> ont un dessin et sont mis en avant ; les autres cartes vont dans « Et aussi », où leurs lignes « - » s&#39;affichent en étiquettes. La <strong>Pastille</strong> ajoute une mention comme « Nouveau ».</li><li><strong>Cartes Référentiels</strong> : le titre est la question, la description la réponse, et <strong>Où cela se règle</strong> la troisième colonne du tableau.</li><li><strong>En bref</strong>, <strong>Enseignement supérieur</strong> et <strong>Chez vous</strong> : le titre suffit ; la description, facultative, s&#39;affiche dessous.</li></ul><p>L&#39;en-tête de la mise en page <strong>Illustrée</strong> rappelle aussi, sous les boutons, que les admissions en ligne sont gratuites sans limite de durée et la durée de la démonstration, reprise des réglages de la plateforme (60 jours par défaut).</p><h3 id="ce-que-montre-le-configurateur-de-tarifs" tabindex="-1">Ce que montre le configurateur de tarifs <a class="header-anchor" href="#ce-que-montre-le-configurateur-de-tarifs" aria-label="Permalink to &quot;Ce que montre le configurateur de tarifs&quot;">​</a></h3><p>Le visiteur coche les pôles et modules qu&#39;il veut ; l&#39;estimation se met à jour à côté :</p><ul><li><strong>Choisir la licence complète du pôle</strong> coche d&#39;un coup tous les pôles de l&#39;enseignement scolaire, facturés au prix de l&#39;offre complète (réglé dans <strong>Conditions tarifaires</strong>).</li><li><strong>Total an 1</strong> additionne la licence, la maintenance de la première année et l&#39;hébergement choisi.</li><li><strong>Dès l&#39;an 2, par an</strong> donne ce qui revient chaque année : la maintenance, plus l&#39;hébergement clé en main s&#39;il est choisi.</li><li>La GED et les modules complémentaires restent « Sur devis » ; la note sous le total rappelle la durée de la démonstration.</li></ul><p>Le texte d&#39;introduction par défaut cite le taux de maintenance réglé dans <strong>Conditions tarifaires</strong> : changer le taux met le texte à jour.</p><h2 id="traiter-les-demandes-de-contact" tabindex="-1">Traiter les demandes de contact <a class="header-anchor" href="#traiter-les-demandes-de-contact" aria-label="Permalink to &quot;Traiter les demandes de contact&quot;">​</a></h2><p>Le formulaire de la vitrine envoie ses demandes dans l&#39;écran <strong>Demandes de contact</strong>. Le nombre de demandes encore à traiter s&#39;affiche en pastille à côté de son nom, dans le menu du panel.</p><p>Chaque demande indique l&#39;établissement, le nom de la personne, la date, la langue dans laquelle elle consultait la vitrine, son e-mail et son téléphone (cliquables) et son message. Les demandes <strong>À traiter</strong> apparaissent en premier, les plus récentes d&#39;abord.</p><p>Une fois l&#39;établissement recontacté, cliquez sur <strong>Marquer comme traitée</strong>. <strong>Remettre à traiter</strong> annule ce marquage.</p><h2 id="mettre-en-place-le-paiement-en-ligne-d-un-etablissement" tabindex="-1">Mettre en place le paiement en ligne d&#39;un établissement <a class="header-anchor" href="#mettre-en-place-le-paiement-en-ligne-d-un-etablissement" aria-label="Permalink to &quot;Mettre en place le paiement en ligne d&#39;un établissement&quot;">​</a></h2><p>Un établissement demande le paiement en ligne depuis son espace (<strong>Finances → Paiement en ligne</strong>). Sa demande arrive dans l&#39;écran <strong>Paiement en ligne</strong> du panel ; le nombre de nouvelles demandes s&#39;affiche en pastille dans le menu.</p><p>Chaque demande donne ce dont l&#39;opérateur a besoin pour ouvrir le compte marchand : raison sociale, responsable légal, RCCM, NIF, numéro de reversement des fonds, ainsi que le nom, l&#39;e-mail et le téléphone de la personne qui a fait la demande. Les demandes ouvertes apparaissent en premier, les plus anciennes d&#39;abord.</p><ol><li>Rappelez l&#39;établissement pour convenir de la mise en place, qui est payante et se règle en dehors de la plateforme. Passez la demande en <strong>En cours</strong> et, si utile, laissez une <strong>Note pour l&#39;école</strong> : l&#39;établissement la lit sur sa page Paiement en ligne.</li><li>Une fois le paiement reçu, ouvrez à la main le compte marchand de l&#39;établissement chez l&#39;opérateur (PayGate aujourd&#39;hui).</li><li>Cliquez sur <strong>Configurer le paiement</strong> (le même écran s&#39;ouvre depuis la liste des établissements, bouton <strong>Paiement en ligne</strong>).</li><li>Choisissez l&#39;<strong>Opérateur</strong>, saisissez la <strong>Clé d&#39;API</strong> du compte, la <strong>Majoration des paiements en ligne</strong> éventuelle (en %, pour couvrir la commission de l&#39;opérateur ; les paiements à la caisse ne sont jamais majorés), cochez <strong>Les parents peuvent payer en ligne</strong>, puis enregistrez.</li><li>Copiez l&#39;<strong>Adresse de retour (webhook)</strong> affichée et collez-la dans le tableau de bord du compte chez l&#39;opérateur, comme adresse de confirmation des paiements. Sans elle, les paiements resteraient « En attente ».</li></ol><p>À l&#39;activation, les administrateurs de l&#39;établissement reçoivent un e-mail, et la demande passe d&#39;elle-même en <strong>Activée</strong>. Une demande non retenue se passe en <strong>Refusée</strong> : l&#39;établissement peut alors en envoyer une nouvelle.</p><p>Chaque établissement a son propre compte marchand : les clés d&#39;API ne sont jamais réaffichées une fois enregistrées (laissez le champ vide pour les garder), et le fichier de configuration du serveur n&#39;est jamais utilisé pour un établissement hébergé. Pour suspendre le paiement en ligne, décochez <strong>Les parents peuvent payer en ligne</strong> et enregistrez.</p>',75)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
